"""Legacy-compatible Meridian CRM RBAC permission check."""

from typing import Any


def can(
    user: dict,
    action: str,
    object: str,
    record: dict,
    role_rows: list[dict],
) -> bool:
    """Return whether the user may perform action on object and record."""
    role_id = user.get("ROLE_ID", "")

    matching_row: dict[str, Any] | None = None
    for row in role_rows:
        if (
            row.get("role_id", "") == role_id
            and row.get("object", "") == object
            and row.get("action", "") == action
        ):
            matching_row = row
            break

    if matching_row is None:
        return False

    if action == "DELETE":
        delete_flag = record.get("DEL_FLG", "")
        if delete_flag == "":
            delete_flag = "N"
        if delete_flag != "N":
            return False

    if role_id == "ADMIN":
        return True

    scope = matching_row.get("scope", "")

    if scope == "ALL":
        return True
    if scope == "TEAM":
        return user.get("TEAM_CD", "") == record.get("TEAM_CD", "")
    if scope == "OWN":
        return record.get("OWNER_UID", "") == user.get("USR_ID", "")

    return False
